"""Find terminal room for an exact leg or a tangent-constrained smooth join."""
import bpy

NAME='Prochitecture Streets / Terminal leg lookahead v1'


def build():
    old=bpy.data.node_groups.get(NAME)
    if old:return old
    from ..kernel.backend_runtime import Graph, V, choose, named, rm
    from ..kernel import prepare
    g=Graph(NAME)
    g.socket('Sources','NodeSocketGeometry');g.socket('Carrier','NodeSocketGeometry')
    g.socket('Geometry','NodeSocketGeometry','OUTPUT')
    inp=g.node('NodeGroupInput');sources=inp.outputs['Sources']
    # The Bundle cut axis uses complete Section endpoint displacements, while
    # the terminal-room guard below still uses only the actual first leg.
    first=named(g,'st_path_start','INT')
    final=first+named(g,'st_path_count','INT')-1.
    chain_start=named(g,'st_bundle_chain_start','INT')
    chain_end=named(g,'st_bundle_chain_end','INT')
    chain_field=g.node('GeometryNodeInputNamedAttribute');chain_field.data_type='INT'
    chain_field.inputs['Name'].default_value='st_bundle_chain_start'
    chain_present=V(g,chain_field.outputs['Exists'])*g.math('GREATER_THAN',chain_start,-.5)
    first=choose(g,chain_present,chain_start,first,'INT')
    final=choose(g,chain_present,chain_end,final,'INT')
    endpoint=choose(g,named(g,'st_path_end','INT'),final,first,'INT')
    opposite=choose(g,named(g,'st_path_end','INT'),first,final,'INT')
    a0=g.separate(prepare.sample(g,sources,g.position(),endpoint,'FLOAT_VECTOR'))
    b0=g.separate(prepare.sample(g,sources,g.position(),opposite,'FLOAT_VECTOR'))
    carrier=g.store(inp.outputs['Carrier'],'st_bundle_axis_delta',
                    g.xyz(*(b0[k]-a0[k] for k in range(3))),'POINT','FLOAT_VECTOR')
    members=prepare.view(g,carrier,5)
    ri=g.node('GeometryNodeRepeatInput','Read every actual terminal leg')
    ro=g.node('GeometryNodeRepeatOutput','Update temporary endpoint rays')
    ri.pair_with_output(ro);g.bind(carrier,ri.inputs['Geometry'])
    g.bind(rm.count(g,members),ri.inputs['Iterations']);at=V(g,ri.outputs['Iteration'])
    start=rm.read(g,members,'st_path_start',at,'INT')
    count=rm.read(g,members,'st_path_count',at,'INT');last=start+count-1.
    end=rm.read(g,members,'st_path_end',at,'INT')
    ep=choose(g,end,last,start,'INT');nxt=choose(g,end,last-1.,start+1.,'INT')
    a=g.separate(prepare.sample(g,sources,g.position(),ep,'FLOAT_VECTOR'))
    b=g.separate(prepare.sample(g,sources,g.position(),nxt,'FLOAT_VECTOR'))
    direction=[b[i]-a[i] for i in (0,1)]
    length=g.math('SQRT',sum(v*v for v in direction));direction=[v/length for v in direction]
    x,y,_=g.separate(g.position());idx=prepare.index(g)
    distance=g.math('ABSOLUTE',(x-a[0])*direction[1]-(y-a[1])*direction[0])
    inrange=g.math('GREATER_THAN',idx,start-.5)*g.math('LESS_THAN',idx,last+.5)
    off=inrange*g.math('GREATER_THAN',distance,1e-5)
    firstoff=prepare.stat(g,sources,choose(g,off,idx,last+1.),'Min')
    lastoff=prepare.stat(g,sources,choose(g,off,idx,start-1.),'Max')
    effective=choose(g,end,lastoff+1.,firstoff-1.,'INT')
    far=prepare.sample(g,sources,g.position(),effective,'FLOAT_VECTOR')
    # Smooth interpolation can leave the mouth with its imposed tangent and
    # reach the first off-ray control. A redundant on-ray control swallowed by
    # the junction is not the end of that available space. Exact mode must
    # still stop at the actual bend. Project only the FIRST off-ray control;
    # later returning segments must never extend the junction through a bend.
    off_index=choose(g,end,lastoff,firstoff,'INT')
    has_off=g.math('GREATER_THAN',off_index,start-.5)*g.math('LESS_THAN',off_index,last+.5)
    off_point=g.separate(prepare.sample(g,sources,g.position(),off_index,'FLOAT_VECTOR'))
    station=sum((off_point[i]-a[i])*direction[i] for i in (0,1))
    far_components=g.separate(far)
    far_station=sum((far_components[i]-a[i])*direction[i] for i in (0,1))
    # Each endpoint belongs to a single normalized Section, so adapting its
    # constant EDGE mode to POINT preserves the same discrete mode.
    mode=prepare.sample(g,sources,named(g,'st_interpolation','INT'),ep,'INT')
    smooth=rm.equal(g,mode,3)*has_off*g.math('GREATER_THAN',station,far_station+.001)
    projected=g.xyz(a[0]+station*direction[0],a[1]+station*direction[1],a[2])
    far=choose(g,smooth,projected,far,'VECTOR')
    localfar=rm.read(g,members,'s2_far_vertex',at,'INT')
    move=g.node('GeometryNodeSetPosition','Effective far point stays on terminal tangent')
    g.bind(ri.outputs['Geometry'],move.inputs['Geometry'])
    g.bind(rm.equal(g,prepare.index(g),localfar),move.inputs['Selection']);g.bind(far,move.inputs['Position'])
    g.bind(move.outputs['Geometry'],ro.inputs['Geometry'])
    out=g.node('NodeGroupOutput');g.bind(ro.outputs['Geometry'],out.inputs['Geometry'])
    g.g['smooth_join_support']=1
    return g.g
